-- Bar, wallpaper
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- Core components (authentication, lock screen, notification daemon)

-- Audio

-- Clipboard: history
-- exec-once = wl-paste --watch cliphist store &

-- Cursor

-- Fix dock pinned apps not launching properly (https://github.com/end-4/dots-hyprland/issues/2200)
-- This causes https://github.com/end-4/dots-hyprland/issues/2427
-- exec-once = sleep 3.5 && hyprctl reload && sleep 0.5 && touch ~/.config/quickshell/ii/shell.qml
-- For fedora to setup polkit

hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/hypr/hyprland/scripts/start_geoclue_agent.sh")
    hl.exec_cmd("qs -c ii &")
    hl.exec_cmd("~/.config/hypr/custom/scripts/__restore_video_wallpaper.sh")
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("dbus-update-activation-environment --all")
    hl.exec_cmd("sleep 1 && dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("~/.config/hypr/scripts/PortalHyprland.sh")
    hl.exec_cmd("easyeffects --hide-window --service-mode")
    hl.exec_cmd("wl-paste --type text --watch bash -c 'cliphist store && qs -c ii ipc call cliphistService update'")
    hl.exec_cmd("wl-paste --type image --watch bash -c 'cliphist store && qs -c ii ipc call cliphistService update'")
    hl.exec_cmd("hyprctl setcursor Bibata-Modern-Classic 24")
    hl.exec_cmd("/usr/libexec/kf6/polkit-kde-authentication-agent-1")
end)

